            var divider = line.IndexOf(':');
            if (divider <= 0) continue;
            var label = global::ProcessLens.Core.SysPulseLocalization.Map(line[..divider],__s=>__s.Trim());
            var value = global::ProcessLens.Core.SysPulseLocalization.Map(line[(divider + 1)..],__s=>__s.Trim());
            var group = TechnicalGroup(label);
            rows.Add(new Fact(group, label, value));
