        string group = EvidenceGroup(cleaned);
        string label = EvidenceDisplayLabel(prefix);

        // Soltanto le evidenze di classificazione prodotte dal programma
        // vengono divise visivamente nei sotto-elementi delimitati da "; ".
        // Non si analizzano né si modificano righe di comando arbitrarie.
        bool structured = prefix.StartsWith(global::ProcessLens.Core.SysPulseLocalization.Literal("Identità"), StringComparison.OrdinalIgnoreCase)
            || prefix.StartsWith(global::ProcessLens.Core.SysPulseLocalization.Literal("Applicazione associata"), StringComparison.OrdinalIgnoreCase)
            || prefix.StartsWith(global::ProcessLens.Core.SysPulseLocalization.Literal("Funzione del processo"), StringComparison.OrdinalIgnoreCase)
            || prefix.StartsWith(global::ProcessLens.Core.SysPulseLocalization.Literal("Ambiente di esecuzione"), StringComparison.OrdinalIgnoreCase)
            || prefix.StartsWith(global::ProcessLens.Core.SysPulseLocalization.Literal("Appartenenza"), StringComparison.OrdinalIgnoreCase)
            || prefix.StartsWith(global::ProcessLens.Core.SysPulseLocalization.Literal("Ruolo"), StringComparison.OrdinalIgnoreCase)
            || prefix.StartsWith(global::ProcessLens.Core.SysPulseLocalization.Literal("Framework"), StringComparison.OrdinalIgnoreCase);
        var parts = structured
            ? detail.Split(global::ProcessLens.Core.SysPulseLocalization.Literal("; "), StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            : new[] { detail };
        foreach (var part in parts)
        {
            string itemLabel = label;
            string itemValue = part;
            int equals = part.IndexOf(global::ProcessLens.Core.SysPulseLocalization.Literal(" = "), StringComparison.Ordinal);
            if (structured && equals > 0 && equals < 80)
            {
                itemLabel = MetadataDisplayLabel(global::ProcessLens.Core.SysPulseLocalization.Map(part[..equals],__s=>__s.Trim()), label);
                itemValue = global::ProcessLens.Core.SysPulseLocalization.Map(part[(equals + 3)..],__s=>__s.Trim());
            }
            else if (part.StartsWith(global::ProcessLens.Core.SysPulseLocalization.Literal("knowledge:"), StringComparison.OrdinalIgnoreCase))
                itemLabel = global::ProcessLens.Core.SysPulseLocalization.Literal("Identificativo della regola interna");
            yield return new Fact(group, itemLabel,
                string.IsNullOrWhiteSpace(itemValue) ? global::ProcessLens.Core.SysPulseLocalization.Literal("Non specificato") : itemValue);
        }
