    private static string MetadataDisplayLabel(string key, string fallback)
    {
        if (key.Equals(global::ProcessLens.Core.SysPulseLocalization.Literal("descrizione file"), StringComparison.OrdinalIgnoreCase)) return global::ProcessLens.Core.SysPulseLocalization.Literal("Descrizione del file eseguibile");
        if (key.Equals(global::ProcessLens.Core.SysPulseLocalization.Literal("prodotto"), StringComparison.OrdinalIgnoreCase)) return global::ProcessLens.Core.SysPulseLocalization.Literal("Nome prodotto");
        if (key.Equals(global::ProcessLens.Core.SysPulseLocalization.Literal("publisher metadata"), StringComparison.OrdinalIgnoreCase)) return global::ProcessLens.Core.SysPulseLocalization.Literal("Editore dichiarato");
        if (key.Equals(global::ProcessLens.Core.SysPulseLocalization.Literal("identità package Windows"), StringComparison.OrdinalIgnoreCase)) return global::ProcessLens.Core.SysPulseLocalization.Literal("Identificativo pacchetto Windows");
        if (key.Equals(global::ProcessLens.Core.SysPulseLocalization.Literal("AUMID Windows"), StringComparison.OrdinalIgnoreCase)) return global::ProcessLens.Core.SysPulseLocalization.Literal("Identificativo applicazione Windows (AUMID)");
        return key.Length > 64 ? fallback : key;
    }

    private static string EvidenceDisplayLabel(string prefix)
    {
        if (prefix.StartsWith(global::ProcessLens.Core.SysPulseLocalization.Literal("Identità"), StringComparison.OrdinalIgnoreCase)) return global::ProcessLens.Core.SysPulseLocalization.Literal("Identificazione dell'eseguibile");
        if (prefix.StartsWith(global::ProcessLens.Core.SysPulseLocalization.Literal("Appartenenza"), StringComparison.OrdinalIgnoreCase) ||
            prefix.StartsWith(global::ProcessLens.Core.SysPulseLocalization.Literal("Applicazione associata"), StringComparison.OrdinalIgnoreCase)) return global::ProcessLens.Core.SysPulseLocalization.Literal("Applicazione associata");
        if (prefix.StartsWith(global::ProcessLens.Core.SysPulseLocalization.Literal("Ruolo"), StringComparison.OrdinalIgnoreCase) ||
            prefix.StartsWith(global::ProcessLens.Core.SysPulseLocalization.Literal("Funzione del processo"), StringComparison.OrdinalIgnoreCase)) return global::ProcessLens.Core.SysPulseLocalization.Literal("Funzione del processo");
        if (prefix.StartsWith(global::ProcessLens.Core.SysPulseLocalization.Literal("Framework"), StringComparison.OrdinalIgnoreCase) ||
            prefix.StartsWith(global::ProcessLens.Core.SysPulseLocalization.Literal("Ambiente di esecuzione"), StringComparison.OrdinalIgnoreCase)) return global::ProcessLens.Core.SysPulseLocalization.Literal("Ambiente di esecuzione");
        if (prefix.StartsWith(global::ProcessLens.Core.SysPulseLocalization.Literal("Origine"), StringComparison.OrdinalIgnoreCase)) return global::ProcessLens.Core.SysPulseLocalization.Literal("Origine del processo");
        if (prefix.StartsWith(global::ProcessLens.Core.SysPulseLocalization.Literal("knowledge:"), StringComparison.OrdinalIgnoreCase)) return global::ProcessLens.Core.SysPulseLocalization.Literal("Identificativo della regola interna");
        return prefix.Length > 65 ? global::ProcessLens.Core.SysPulseLocalization.Concat(prefix[..65],global::ProcessLens.Core.SysPulseLocalization.Literal("…")) : prefix;
    }

