            || label.StartsWith(global::ProcessLens.Core.SysPulseLocalization.Literal("Thread"), StringComparison.OrdinalIgnoreCase)
            || label.StartsWith(global::ProcessLens.Core.SysPulseLocalization.Literal("Handle"), StringComparison.OrdinalIgnoreCase))
            return global::ProcessLens.Core.SysPulseLocalization.Literal("Risorse");

        if (label.StartsWith(global::ProcessLens.Core.SysPulseLocalization.Literal("PID -"), StringComparison.OrdinalIgnoreCase)
            || label.StartsWith(global::ProcessLens.Core.SysPulseLocalization.Literal("Famiglia"), StringComparison.OrdinalIgnoreCase)
